entity icg_cell is
port(
  ck         : in std_logic;        --Clock input
  ce         : in std_logic;        --Clock enable
  d          : in std_logic;        --Data input
  q          : out std_logic;       --Q output
  enable     : in std_logic;        --Enable control
  ck_out     : out std_logic;       --Output clock
  ck_glitch  : out std_logic
);
end entity;
    architecture behave of icg_cell is
signal ce_glitch : std_logic;      --Signal to detect CE glitch
begin
  process(ck, q, d, ce)
  begin
    if ce = '1' then
      if ce_glitch = '1' then
        q <= d;
        ce_glitch <= '0';
      else 
        ce_glitch <= '1';
        --Glitch detection and handling logic here
      end if;
    else
      q <= '0'; -- Keep previous state when not enabled
    end if;
  end process;
